def min_rooms(events):
    # Sort events by start time
    sorted_events = sorted(events, key=lambda x: x[0])

    # Use a list to track the end times of rooms currently in use
    rooms = []

    for start, end in sorted_events:
        # If any room is free by the time this event starts, reuse it
        rooms.sort()
        if rooms and rooms[0] <= start:
            rooms[0] = end
        else:
            # Otherwise, we need a new room
            rooms.append(end)

    return len(rooms)

events = [(9, 11), (10, 12), (11, 13), (12, 14)]
print(min_rooms(events))

